export async function generateAppJwt(): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  return jwt.sign(
    { iat: now - 60, exp: now + 600, iss: GITHUB_APP_ID },
    GITHUB_APP_PRIVATE_KEY,
    {
      algorithm: 'RS256',
    }
  );
}

